from pathlib import Path
import json,shutil
O=Path('outputs');d=json.loads((O/'language_variants_audit.json').read_text());c=d['cot'];pct=lambda n:f'{n*100:.1f}%'
def cot(name):
 r=c[name];return f'{pct(r["rate"])} versus matched base {pct(r["matched_base"])}; {r["items"]} items, {r["samples"]} generations; paired 95% CI for gain [{r["gain_ci95"][0]*100:+.1f}, {r["gain_ci95"][1]*100:+.1f}] percentage points'
intro=('We tried language rewards on the reasoning and on the final answer, supervised training on translated reasoning, and several attempts to learn French reasoning from response-only requests. Direct CoT-language RL produced the clearest transfer to other deterministic CoT rules, while the answer-language reward left this metric near baseline. Translated SFT improved language following, including an untrained language, but its broader rule-control gain was weak at the final checkpoint. Back-translated English reasoning gave a larger rule-control gain, so multilingual content alone does not explain the SFT result. These are single developed runs with different evaluation subsets and incomplete pilot records; the details below separate held-out evaluations from training-batch diagnostics.')
sections=[]
sections.append('1. Explicit reasoning-language GRPO (lang1, lang2). Reward French, Spanish, or German reasoning, weighted by answer correctness, with a base-relative length penalty; reasoning remains enabled and the sampled completion receives policy updates. lang1 at step20: '+cot('lang1-s20')+'. At step40: '+cot('lang1-s40')+'. The implicit French-cue results on this slide use lang1 step40. lang2 removes the F0 reference prompt frame (p_ref=0), but still samples the term “analysis channel” among the other terms; it is NOT an ablation removing every mention of that channel. At its saved step18: '+cot('lang2-s18')+'. Different step counts and a single run prevent a clean causal attribution to the frame change.')
sections.append('2. Final-answer-language GRPO (lang-ans1). Reward a short final explanation in French, Spanish, or German; the language reward grades the visible response, while the policy update still covers the generated completion, including reasoning. At step20: '+cot('lang-ans1-s20')+'. This provides no detectable transfer on this benchmark. The comparison is imperfect: lang-ans1 uses the R frame with user placement, unlike lang1’s frame/placement mixture, and the base policy already often satisfies the answer-language request. It does not establish that every kind of answer-only feedback has no spillover.')
lang=d['language_noformat'];after={k.rsplit('/',1)[1]:v for k,v in lang.items() if 'step20/' in k}
sections.append('3. Translated-reasoning SFT (langsft1). One epoch, 20 optimizer steps, 315 examples: 75 French, 83 Spanish, 82 German, and 75 unchanged English. Both question and the model’s own correct English CoT are translated; no explicit reasoning-language instruction is included, and completion cross-entropy trains the CoT and final answer. On translated questions with no answer-format line (50 examples per language), strict target-language reasoning goes from 0/50 in each language to '+', '.join(f'{after[L]["strict"]}/50 in {L}' for L in ['French','Spanish','Italian'])+'. Italian was absent from training. These language scores include truncated traces (8 French, 5 Spanish, 3 Italian outputs at step20) and use a stopword-based detector, not a semantic fluency judge. On separate deterministic CoT rules: step8 '+cot('langsft1-s8')+'; step20 '+cot('langsft1-s20')+'. Stronger language following therefore did not produce a monotonic increase in broad rule control.')
sections.append('4. SFT controls on the original 96 deterministic CoT items (four generations per item; matched base 2.3%). Own unchanged English traces: '+cot('langsft1-en-s20')+'. Translated then back-translated English traces: '+cot('langsft1-back-s20')+'. DeepSeek-generated English traces: '+cot('langsft1-ds-s20')+'. The first two use the same 315 selected examples as translated SFT; the DeepSeek set has 313 after correctness filtering. The back-translation result weakens a language-specific explanation and motivates checking which rewriting changes matter. It does not by itself identify the mechanism.')
sections.append('5. Simple rewriting controls. Random synonym/phrase substitutions throughout the original English traces (langsft1-noise): '+cot('langsft1-noise-s20')+'. Changes restricted to the last two sentences/lines, including output/formatting wording (langsft1-end): '+cot('langsft1-end-s20')+'. Neither control reproduces the back-translation gain. The stripped-ending dataset was built but was abandoned after very few traces changed; no outcome is asserted for it.')
tr=d['training'];hot=tr['fr-hot'];shape=tr['fr-shaped'];mix=tr['fr-mix'];warm=tr['fr-from-lang1']
sections.append(f'6. Learning French CoT from response-only requests. fr-hot raises sampling temperature to1.3 and rewards French reasoning despite only requesting a French response: {hot["strict_total"]}/{hot["n"]} raw strict successes across the {len(hot["steps"])} saved training steps. fr-shaped rewards French in the front half of the reasoning with larger rollout groups: {shape["strict_total"]}/{shape["n"]} strict successes, but only one saved step. fr-mix mixes explicit and implicit French requests with a planned curriculum: {mix["strict_total"]}/{mix["n"]} strict successes, also only one saved step. The latter two are incomplete pilot records, not completed negative experiments. Initializing from lang1 step40 (fr-from-lang1) yields {warm["strict_total"]}/{warm["n"]} raw strict successes over {len(warm["steps"])} saved steps; this demonstrates an already available behavior, not a newly measured held-out gain from the continuation. Counts here pool changing training policies and retain raw style passes even when completion gates fail, so they are not comparable to held-out success rates.')
sections.append('Metric and verification. CoT-rule comparisons exclude semantic ignore_question, average samples within each item, and allow meta discussion without requiring a correct answer. This matches the earlier main slides; older dashboard summaries include ignore_question and therefore have different totals and rates. All displayed rule scores were freshly regraded and matched saved deterministic labels. Language scores were independently recomputed with the saved stopword detector (at least3 classified spans, at least95% in the target language). Paired gain intervals bootstrap normalized question clusters, 5,000 draws, seed20261030; they describe evaluation uncertainty, not training-seed variation. Seeded beginning/end excerpts were inspected, with full semantic correctness and fluency uncalibrated; some strict rule passes are very short or degenerate. Training pilot tallies were independently counted from saved rollouts but are not new held-out evaluations. No model training or inference was run for this update.')
sections.append('Sources. nocotrl-b-pilot/cot-control/results/rl/{lang1,lang2,lang-ans1,langsft1,langsft1-en,langsft1-back,langsft1-ds,langsft1-noise,langsft1-end,fr-hot,fr-shaped,fr-mix,fr-from-lang1}; results/outctl/{more,big}/cot/*/graded.json; results/outctl/qlang/answer_lang.jsonl; rl/sft_lang.py, rl/grpo_types.py, rl/controls.py, results/outctl/qlang/build_{sft,back,mech}.py. Fresh aggregates, sample sizes, source hashes, and bootstrap seed: outputs/language_variants_audit.json; reproduction: outputs/audit_language_variants.py.')
notes=intro+'\n\n'+'\n\n'.join(sections)
(O/'language_training_backup_notes.txt').write_text(notes)
shutil.copyfile('work/audit_language_variants.py',O/'audit_language_variants.py')
deep=('Rewrite SFT transferred to two styles absent from both the preceding RL training and the SFT examples: French and happy reasoning. With the same 60 evaluation questions per style, recorded strict compliance rises from 0/60 to16/60 for French and from0/60 to46/60 for happy. The SFT data teach seven styles: cover story, sad, shorthand, no backtracking, word suppression, maximum words, and alternating case. Happy is a close transfer from sad, while French introduces a different language objective; these should not be treated as equally distant generalization. Accuracy costs and the incomplete semantic-judge calibration remain visible in the table, and the preceding backup covers the one known prior-RL-pool question overlap.')
(O/'deepseek_transfer_backup_notes.txt').write_text(deep)
p=O/'generalization_new_cot_tasks.json';x=json.loads(p.read_text());x['status']='Scrapped as a main slide at user request; DeepSeek result retained in backup p6, language variants documented in gen_language speaker notes.';p.write_text(json.dumps(x,indent=2))
p=O/'generalization_new_cot_tasks.html';s=p.read_text();s=s.replace('<h1>','<p><b>Retired main-slide draft. DeepSeek transfer and language-training notes are retained in the shared backup deck.</b></p><h1>',1);p.write_text(s)
print(json.dumps({'intro':intro,'notes_chars':len(notes),'deepseek':deep},indent=2))
